"""
mission_store.py  — REPLACE entire file with this version
──────────────────────────────────────────────────────────
Adds latest_telemetry as a proper dataclass field so /api/status
never throws AttributeError when polled before any phase-update arrives.
"""

from dataclasses import dataclass, field
from typing import Optional
import paramiko


@dataclass
class MissionStore:
    # Generated by sage_ai.py
    script:  Optional[str]  = None   # Python flight code to deploy
    summary: Optional[str]  = None   # Human-readable mission description
    phases:  Optional[list] = None   # List of phase dicts from AI

    # Runtime state
    is_executing: bool = False
    ssh_client: Optional[paramiko.SSHClient] = None

    # Telemetry — populated by /api/phase-update callbacks from Pi
    # Declared here so getattr(store, "latest_telemetry", None) is never needed
    latest_telemetry: Optional[object] = None   # type: TelemetrySnapshot

    def clear(self):
        """Reset everything between missions."""
        self.script           = None
        self.summary          = None
        self.phases           = None
        self.is_executing     = False
        self.ssh_client       = None
        self.latest_telemetry = None

    def has_mission(self) -> bool:
        return self.script is not None


# Single shared instance — import this everywhere
store = MissionStore()
